```json
{
  "root_causes": [
    {
      "service": "ts-consign-service",
      "fault_kind": "database_call_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) AS n, round(approx_quantile(duration,0.5)/1e6,1) AS p50_ms, round(approx_quantile(duration,0.95)/1e6,1) AS p95_ms FROM abnormal_traces WHERE service_name='ts-consign-service' AND span_name IN ('SELECT ts.consign_record','INSERT ts.consign_record','Transaction.commit') GROUP BY 1,2",
          "claim": "Consign's database client spans slowed sharply: SELECT median ~1450ms, INSERT ~1144ms, versus sub-millisecond normally."
        },
        {
          "kind": "trace",
          "sql": "SELECT round(approx_quantile(duration,0.5)/1e6,1) AS p50_ms, round(approx_quantile(duration,0.95)/1e6,1) AS p95_ms, count(*) AS n FROM abnormal_traces WHERE service_name='ts-consign-service' AND span_name='ConsignRepository.findById'",
          "claim": "Consign repository lookups take seconds (p50 ~8.4s) while the same spans took about 4ms in normal traffic."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' AS src, metric, round(avg(value),3) AS avg_v, round(max(value),3) AS max_v FROM abnormal_metrics WHERE service_name='mysql' AND metric='k8s.pod.cpu.usage' GROUP BY 1,2 UNION ALL SELECT 'nrm', metric, round(avg(value),3), round(max(value),3) FROM normal_metrics WHERE service_name='mysql' AND metric='k8s.pod.cpu.usage' GROUP BY 1,2",
          "claim": "MySQL CPU is flat or lower during the incident (avg 0.026 vs 0.052 cores), so the database server itself is not overloaded."
        },
        {
          "kind": "metric",
          "sql": "SELECT 'abn' AS src, metric, round(avg(value),3) AS avg_v FROM abnormal_metrics_sum WHERE service_name='ts-consign-service' AND metric IN ('db.client.connections.pending_requests','db.client.connections.usage') GROUP BY 1,2 UNION ALL SELECT 'nrm', metric, round(avg(value),3) FROM normal_metrics_sum WHERE service_name='ts-consign-service' AND metric IN ('db.client.connections.pending_requests','db.client.connections.usage') GROUP BY 1,2",
          "claim": "Consign's DB connection pool shows no pending requests in either period, so the delay sits in the calls, not pool queueing."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-consign-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT 'abn' AS src, count(*) AS n, round(approx_quantile(c.duration,0.5)/1e6,1) AS caller_p50_ms, round(approx_quantile(c.duration,0.95)/1e6,1) AS caller_p95_ms, sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) AS callee_errors FROM abnormal_traces c JOIN abnormal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-consign-service' AND s.attr_span_kind='Server' UNION ALL SELECT 'nrm', count(*), round(approx_quantile(c.duration,0.5)/1e6,1), round(approx_quantile(c.duration,0.95)/1e6,1), sum(CASE WHEN s.attr_status_code='Error' THEN 1 ELSE 0 END) FROM normal_traces c JOIN normal_traces s ON s.trace_id=c.trace_id AND s.parent_span_id=c.span_id WHERE c.service_name='ts-ui-dashboard' AND s.service_name='ts-consign-service' AND s.attr_span_kind='Server'",
          "claim": "Dashboard calls into consign went from ~8ms median to ~3.2s median, and six consign calls returned errors."
        }
      ]
    }
  ]
}
